import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第02章 跟着我","description":"","frontmatter":{},"headers":[],"relativePath":"第02章_跟着我.md","filePath":"第02章_跟着我.md"}'),o={name:"第02章_跟着我.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第02章-跟着我" tabindex="-1">第02章 跟着我 <a class="header-anchor" href="#第02章-跟着我" aria-label="Permalink to &quot;第02章 跟着我&quot;">​</a></h1><p>她拉我进那款游戏，是在一个下雨的下午。</p><p>南雾县一下雨就没什么可干的，路是土路，出门踩一脚泥，回来要刷半小时鞋。我趴在阳台的栏杆上看雨，看桥头那盏灯在水里碎成一堆亮片。她在那头说，你下个游戏吧。我说我不玩游戏。她说那你现在开始玩。我问为什么。</p><p>她说：因为我玩。</p><p>我就去下了。那款游戏很大，我家的网很慢，装了一下午，她每隔一会儿问一句好了没。我说没。她说你家的网是纸做的吗。我说差不多。她说那你今天别想玩了。我说那我明天再玩。她说，明天就来不及了。我问来不及什么，她没答，过了一会儿只说你先下，下好了叫我。</p><p>我把手机放在桌上，看进度条一截一截往前爬。爬到一半卡住了，不动。我把路由器拔了重插，等它重新连上，进度条又慢慢走。那个路由器在电视柜上面，我要踩着一把椅子才能够到。我爬上去的时候奶奶正好进来，她抬头看我挂在柜子上面，问我干什么。我说重启。她说重启什么。我说网。她哦了一声，把那个扫把靠在墙边，没走，就站在那儿看我下来。</p><p>她问，网坏了？</p><p>我说没坏，我在下个东西。</p><p>她说下什么东西要下这么久。我答不上来。</p><p>天阴着，五点多就暗了。我把屋里的灯开了，泡一碗面，边吃边守着屏幕。</p><p>那会儿她也在等。她给我发她屋里的事：她妹妹在看电视，声音开得很大；她妈在厨房收拾，把锅磕得咔咔响；她自己靠在一张小桌子上写作业，写完一页就抬头看我回没回。我问她家里没人管她看手机吗。她说管。我说那你还玩。她说趁他们不注意。我说那不就得删记录。她说你不懂，隔几秒又补一条：我比你懂。</p><p>我那时候真不懂。我只觉得她挺大胆。后来我才知道那不是大胆，是习惯——一件事你每次都小心，时间长了就不叫小心了，那叫日子。</p><p>装好已是傍晚。她让我建号取名字，我想了半天取了一个很正经的，她说土。我说那你给我取。她说不取，你自己想，想不出来别玩了。我改了三次，第三次她勉强说凑合吧。</p><p>进游戏，她已经在里面等我了。她的角色比我大好几级，走路带风。</p><p>她说：跟着我。</p><p>我跟着她。走到第一处水边，我掉下去了。她问你往哪走呢，我说我不知道怎么停。她说按那个键，你手呢。我说我按了。她问你按的是哪只，我说左手。她说你换右手。我换了，爬上来，走三步又掉下去。她在那边笑了一长串，笑得我耳朵发烫，笑完说：你站着别动，我回来接你。</p><p>我说那你也掉下来怎么办。</p><p>她说：我掉下来我们就一起死。</p><p>我说那不行。她说那你就别动。</p><p>她的角色从远处跑回来，站在岸边转了个圈，说看准我脚下，走我走过的地方。我就跟着她的脚印走。她走得很慢，一步一步，像在等我。走到一半她停下来，说你踩到草了。我说草怎么了。</p><p>她说：草会记住的。</p><p>我说游戏里哪来的草会记住。她说，我说会就会。</p><p>过了水她带我往山上走。路上她捡了一堆东西，边走边丢，丢完再捡。我问她在干什么，她说攒着，以后有用。我问有什么用，她说到时候你就知道了。她说什么都是这样，从来不一次把话说完，总要留半截让你自己去想。我那时以为那是她的性格，后来才发现，她只是习惯了不把话说满。</p><p>那天晚上她带我去看她的家——游戏里的一块地，她盖了房子，歪歪扭扭，墙没对齐，屋顶还是漏的。她说你别笑，我说我没笑。她说你心里笑了。</p><p>她让我在她家旁边也盖一间。我说我不会。她说很简单，你先放一块地基。我放了，放歪了，跟她的房子错开半个身位，中间空出一条缝。她说你盖得歪。我说那怎么办。她说算了。</p><p>然后她把那间房子改成小一点的，往我这边挪了挪，正好把那条缝填上。两块地基贴在一起，像两枚齿咬住的梳子。</p><p>我问她，这样算谁家。</p><p>她说，算我们家的。</p><p>我问她这块地什么时候盖的。她说很早。我问多早。</p><p>她说：我一个人的时候。</p><p>她讲这句的时候语气很平，像在说今天吃了什么。我没接。我那时候不懂&quot;一个人的时候&quot;是什么意思，只觉得这几个字有点沉。我又问她建这块地时几年级，她想了想说初一。我说初一你就玩这个。她说初一的时候我谁都不认识。我问那现在呢。</p><p>她说：现在认识你了。</p><p>她带我绕着房子走一圈。院子边上放着几个箱子，盖着，看不出里面是什么。我问能不能打开。她说不能。我说锁了吗。她说没锁，但是不能打开。我问为什么。</p><p>她说：有些东西开过一次就旧了。</p><p>那天她的头像黑下去以后，我在那块地上坐到很晚。游戏里有昼夜，天黑了，她家屋顶那个破洞里能看见星星。我试着跳了一下，跳不上去，就原地坐着。我那时候还不知道自己在做什么，只觉得屏幕上有这么一块地方，两个歪房子拼在一起，中间那条缝是她挪过来填的。</p><p>后来我才明白，那是我第一次想让一件事长久一点。</p><p>那晚临睡前她发来一条：以后你就跟着我。我回好。她又说你要是自己乱跑，我就不带你了。我说我不乱跑。她说，记住你今天说的。</p><p>我记住了。我也真的没乱跑。我后来几年的很多选择都是在那天晚上定的：跟着她，等她，别乱走。我以为那是一种忠诚。很久以后我才知道，一个人不肯走开，有时候只是因为不敢往别的地方看。</p><p>第二天早上她说她要去补作业，要消失几天。我说好。她问你会无聊吗。我说不会。她说骗人。</p><p>然后她发来一张图，是她那间歪房子的截图，屋顶的破洞里有一颗很亮的星星。</p><p>她说：给你了。</p>',41)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
